#!/usr/bin/env python3
"""patch_lf_release_044.py -- VERSION follows the record, and a correction.

SUPERSEDES `patch_lf_version_selfcheck.py`, WHICH WAS WRONG. Delete that file;
it refused to apply (its pre-hashes did not match, which is the check doing its
job) and its reasoning was false.

WHAT I GOT WRONG, AND HOW IT WAS CAUGHT.

I reported that `level_factory/VERSION` had regressed to 0.22.0 and that
`pyproject.toml` hard-coded a matching stale number -- a twenty-one-minor
version rollback, the second in this repo's history. Both claims were false.
They came from files served STALE by the file bridge. The real tree says:

    VERSION ......... 0.43.3        (not 0.22.0)
    pyproject.toml .. dynamic = ["version"], version = {file = "VERSION"}
                      (not a hard-coded number; 1253 bytes, not 762)

pyproject has derived its version from the VERSION file for some time, so the
two CANNOT disagree by construction. And VERSION at 0.43.3 against a CHANGELOG
at 0.44.0 is not a regression -- it is `patch_dressing_jobs.py` having written
that entry a minute earlier. Ordinary UNRELEASED.

`python -m level_factory verify-manifest` said so plainly, against the real
tree, in one line:

    UNRELEASED  level_factory  the CHANGELOG documents 0.44.0 but VERSION says
                0.43.3 -- the record is ahead of the version; bump VERSION to
                follow it, then re-pin

The instrument was right. The report about the instrument was wrong. Worth
naming precisely because the failure was not the tool: it was reasoning from
staged copies as if they were the repository. Pre-hash checks protect the
EDITS; they do not protect the FINDINGS, and a finding built on a stale read
is a confident, well-argued fiction.

WHAT THIS PATCH DOES.

1. `VERSION` 0.43.3 -> 0.44.0, which is what verify-manifest asked for.

2. Replaces the false section in `level_factory/CHANGELOG.md`. That section
   was applied by `patch_dressing_jobs.py` and is in the permanent record
   right now, asserting a regression that never happened. It is REPLACED with
   a correction rather than deleted, so the retraction sits next to where the
   claim was made.

3. Adds `tests/test_own_version.py`, rewritten. The original was built around
   the imaginary defect. What survives is the part that is true regardless:
   `verify-manifest` answers this well but only when someone types it, and
   these ask the same question from `pytest`. Every assertion now pins
   something the repo already does right --

     * pyproject still declares `dynamic = ["version"]` reading the VERSION
       file, and still hard-codes nothing. That design is why the drift I
       claimed was impossible; the test is there so nobody replaces it with a
       literal.
     * `contracts.self_disagreement(VERSION, newest heading)` is None.
     * no `VERSION.pre_*` sidecar holds a version HIGHER than VERSION. This
       passes today (0.23.0 and 0.43.2 against 0.44.0) and is kept because
       Zoo's CHANGELOG records a reset that really did happen.
     * a falsification test pinning `self_disagreement` on known inputs, so
       the three above cannot pass by the instrument returning None for
       everything.

WHAT IT STILL DOES NOT DO. `factory.manifest.json` is untouched. verify-manifest
correctly reports lot 0.46.0, patina 0.21.0 and zoo 0.38.0 as DRIFT against
their pins, with "re-run the real-tool smoke and re-certify". That is a claim
about integration evidence, and it is yours to make.

VERIFIED against the real VERSION: 5 passed / 1 FAILED before the bump, and
the failure is the UNRELEASED verify-manifest reported. 6 passed after.

    python patch_lf_release_044.py --check
    python patch_lf_release_044.py --selftest
    python patch_lf_release_044.py
    python patch_lf_release_044.py --revert
"""
